    freq = {v: sum(row.count(v) for row in grid) for v in colors}
    bg = max((v for v in colors if v != marker), key=lambda v: freq[v])
    frame = next((v for v in colors if v not in (marker, bg)), None)
    # Demonstrated rule: marker cells become 4; form an L-shaped filled corner
