    # Fill corner-facing areas based on the side edges that carry frame color.
    top_frame = any(grid[0][c] == frame for c in range(w)) if frame is not None else False
    right_frame = any(grid[r][w-1] == frame for r in range(h)) if frame is not None else False
    if top_frame:
        for r in range(h):
